package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class JsonParserSequence_nextToken_TriageGen0Test {

    /**
     * Test case to cover:
     * 1. t != null (first parser returns a token immediately)
     */
    @Test
    public void testNextToken_FirstParserReturnsToken() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);

        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, parser2);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        verify(parser1, times(1)).nextToken();
        verifyNoInteractions(parser2);
    }

    /**
     * Test case to cover:
     * 1. t == null (first parser is exhausted)
     * 2. switchToNext() returns true
     * 3. second parser returns a token
     */
    @Test
    public void testNextToken_FirstParserEmpty_SecondParserReturnsToken() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, parser2);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(parser1, times(1)).nextToken();
        verify(parser2, times(1)).nextToken();
    }

    /**
     * Test case to cover:
     * 1. t == null (first parser is exhausted)
     * 2. switchToNext() returns true
     * 3. second parser returns null (exhausted)
     * 4. switchToNext() returns false (no more parsers)
     * 5. returns null
     */
    @Test
    public void testNextToken_AllParsersEmpty() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenReturn(null);

        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, parser2);

        JsonToken result = sequence.nextToken();

        assertNull(result);
        verify(parser1, times(1)).nextToken();
        verify(parser2, times(1)).nextToken();
    }

    /**
     * Test case to cover:
     * 1. Exception handling from the delegate parser
     */
    @Test(expected = IOException.class)
    public void testNextToken_ThrowsIOException() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        when(parser1.nextToken()).thenThrow(new IOException("Simulated IO Error"));

        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, mock(JsonParser.class));
        sequence.nextToken();
    }

    /**
     * Test case to cover:
     * 1. Exception handling from the delegate parser during switching
     */
    @Test(expected = JsonParseException.class)
    public void testNextToken_ThrowsJsonParseExceptionOnSecondParser() throws IOException, JsonParseException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);

        when(parser1.nextToken()).thenReturn(null);
        when(parser2.nextToken()).thenThrow(new JsonParseException(null, "Simulated Parse Error"));

        JsonParserSequence sequence = JsonParserSequence.createFlattened(parser1, parser2);
        sequence.nextToken();
    }
}
